{"supportTree":{"version":"1.0","primary_path":[{"id":"intro","action":{"copy":"Start"},"response":{"text":{"type":"text","value":"\text{Find where the two curves intersect. Look at the graph, where do they cross?}"},"expression":{"type":"web","html":"<!doctype html><html lang="en"><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no"/><title>Math Diagram - Simple</title><script>MATH_VISUAL_LIBRARY</script></head><body><div class="diagram-container"><div id="diagram"></div></div><script>/**
       * Get all variables as a dictionary
       * This function returns all variables defined in the variables schema.
       * This includes both input and output variables.
       *
       * Keep the function signature the same. Do no remove the function.
       *
       * @return {Object} Dictionary of all variables with their values. The keys are the variable names (strs).
       */
      function getOutputVariables() {
        return OUTPUT_VARIABLES;
      }

      /**
       * The input variables defined in the variables schema. These values can
       * be configured to parameterize the diagram.
       */
      const INPUT_VARIABLES = {"a_1": 1, "b_1": -4, "c_1": 3, "a_2": -1, "b_2": 2, "c_2": 3};

      /**
       * Set the value of a variable by name. This function should be used to set variable values defined in the variables schema.
       * This function can only set input variables.
       *
       * Keep the function signature the same. Do no remove the function.
       *
       * @param variableName - The name of the variable to set
       * @param value - The value to set the variable to (must be a valid value for the variable)
       * @returns {null}
       */
      function setVariable(variableName, value) {
        INPUT_VARIABLES[variableName] = value;
        // In a real scenario, we might want to re-render the diagram here.
        return null;
      }

      const OUTPUT_VARIABLES = {
        intersection_points: [],
      };

      // Wrap in DOMContentLoaded to ensure the diagram library is fully loaded before running the code.
      addEventListener("DOMContentLoaded", () => {
        // Define constants for the coefficients from INPUT_VARIABLES.
        const { a_1, b_1, c_1, a_2, b_2, c_2 } = INPUT_VARIABLES;

        // Create a grid system
        const grid = new Grid2D({
          gridSize: "MULTI_QUADRANT_LARGE",
          xAxisMin: -5,
          yAxisMin: -5,
          xAxisLabels: true,
          yAxisLabels: true,
          showGrid: true,
          showAxes: true,
        });

        // Create a new math diagram
        const diagram = new MathDiagram({
          container: "#diagram",
          grid: grid,
        });

        // Define the two quadratic functions.
        const f1 = x => a_1 * x * x + b_1 * x + c_1;
        const f2 = x => a_2 * x * x + b_2 * x + c_2;

        // Add the functions to the diagram.
        diagram.addFunction({ fOfX: f1 });
        diagram.addFunction({ fOfX: f2 });

        // Calculate intersection points by setting f1(x) = f2(x)
        // (a_1)x^2 + (b_1)x + c_1 = (a_2)x^2 + (b_2)x + c_2
        // (a_1 - a_2)x^2 + (b_1 - b_2)x + (c_1 - c_2) = 0
        const A = a_1 - a_2;
        const B = b_1 - b_2;
        const C = c_1 - c_2;

        const intersections = [];
        const TOLERANCE = 1e-9; // Tolerance for floating point comparisons

        if (Math.abs(A) < TOLERANCE) {
          // This is a linear equation: Bx + C = 0
          if (Math.abs(B) > TOLERANCE) {
            const x = -C / B;
            const y = f1(x);
            if (
              Math.abs(x - Math.round(x)) < TOLERANCE &&
              Math.abs(y - Math.round(y)) < TOLERANCE
            ) {
              intersections.push({ x: Math.round(x), y: Math.round(y) });
            }
          }
        } else {
          // This is a quadratic equation: Ax^2 + Bx + C = 0
          const discriminant = B * B - 4 * A * C;

          if (discriminant >= 0) {
            const sqrtD = Math.sqrt(discriminant);
            const x1 = (-B + sqrtD) / (2 * A);
            const y1 = f1(x1);
            if (
              Math.abs(x1 - Math.round(x1)) < TOLERANCE &&
              Math.abs(y1 - Math.round(y1)) < TOLERANCE
            ) {
              intersections.push({ x: Math.round(x1), y: Math.round(y1) });
            }

            if (discriminant > 0) {
              const x2 = (-B - sqrtD) / (2 * A);
              // Avoid adding duplicate points if x1 and x2 are very close
              if (Math.abs(x1 - x2) > TOLERANCE) {
                const y2 = f1(x2);
                if (
                  Math.abs(x2 - Math.round(x2)) < TOLERANCE &&
                  Math.abs(y2 - Math.round(y2)) < TOLERANCE
                ) {
                  intersections.push({ x: Math.round(x2), y: Math.round(y2) });
                }
              }
            }
          }
        }

        const draggablePoints = [];
        // Add draggable points at each integer intersection.
        intersections.forEach(p => {
          const draggablePoint = diagram.addDraggablePoint({ x: p.x, y: p.y });
          draggablePoints.push(draggablePoint);
          OUTPUT_VARIABLES.intersection_points.push({ x: p.x, y: p.y });
        });

        // Add update subscribers to track the final positions of the points.
        draggablePoints.forEach((point, i) => {
          point.addUpdateSubscriber(function () {
            OUTPUT_VARIABLES.intersection_points[i] = {
              x: this.x,
              y: this.y,
            };
          });
        });
      });

      // Compute aspect ratio on load
      window.onload = window.computeAndCommunicateAspectRatio;</script></body></html>","metadata":{"ASPECT_RATIO":"1","DIAGRAM_ID":"generated_20250815_034745_070/diagram_8"},"resources":{"MATH_VISUAL_LIBRARY":"https://math-cdn.duolingo.com/visual_library/index_348471925d53b9873fec.js"}}},"secondary":[{"id":"q_intro_what_is_intersection","chip":{"copy":"\text{What are intersection points?}","type":"definition"},"response":{"text":{"type":"text","value":"\text{Intersection points are where both curves share the same }\mathbf{x}\text{ and }\mathbf{y}\text{ value.}"}}},{"id":"q_intro_how_many","chip":{"copy":"\text{How many intersections?}"},"response":{"text":{"type":"text","value":"\text{Set }\mathbf{f_1(x) = f_2(x)}\text{ and count the solutions, each solution gives one intersection point.}"}}},{"id":"q_intro_curve_shapes","chip":{"copy":"\text{What do the curves look like?}"},"response":{"text":{"type":"text","value":"\mathbf{f_1 = x^2 - 4x + 3}\text{ opens upward. }\mathbf{f_2 = -x^2 + 2x + 3}\text{ opens downward. They cross twice!}"}}}]},{"id":"step_1_set_equal","action":{"copy":"Next step"},"response":{"text":{"type":"text","value":"\text{Set }\mathbf{f_1(x) = f_2(x)}\text{: }\mathbf{x^2 - 4x + 3 = -x^2 + 2x + 3}\text{. Simplify: }\mathbf{2x^2 - 6x = 0}\text{, so }\mathbf{2x(x-3) = 0}\text{.}"},"expression":null},"secondary":[{"id":"q_1_why_set_equal","chip":{"copy":"\text{Why set equal?}"},"response":{"text":{"type":"text","value":"\text{Intersection points have the same }\mathbf{x}\text{ and }\mathbf{y}\text{. So set }\mathbf{f_1(x) = f_2(x)}\text{ and solve for }\mathbf{x}\text{.}"}}},{"id":"q_1_how_simplify","chip":{"copy":"\text{How to simplify?}"},"response":{"text":{"type":"text","value":"\text{Move everything to one side: }\mathbf{2x^2 - 6x = 0}\text{. Then factor out }\mathbf{2x}\text{: }\mathbf{2x(x - 3) = 0}\text{.}"}}},{"id":"q_1_what_is_factoring","chip":{"copy":"\text{What is factoring?}","type":"definition"},"response":{"text":{"type":"text","value":"\text{Factoring rewrites an expression as a product. }\mathbf{2x^2 - 6x = 2x(x-3)}\text{. Set each factor to 0 to solve!}"}}}]},{"id":"step_2_answer","action":{"copy":"Next Step"},"response":{"text":{"type":"text","value":"\text{So }\mathbf{x = 0}\text{ or }\mathbf{x = 3}\text{. The intersection points are }\mathbf{(0,\,3)}\text{ and }\mathbf{(3,\,0)}\text{. Plot both!}"},"expression":null},"secondary":[{"id":"q_2_find_y","chip":{"copy":"\text{How to find }\mathbf{y}\text{?}"},"response":{"text":{"type":"text","value":"\text{Plug }\mathbf{x}\text{ back into either equation. }\mathbf{f_1(0) = 3}\text{ and }\mathbf{f_1(3) = 0}\text{.}"}}},{"id":"q_2_why_two_points","chip":{"copy":"\text{Why two points?}"},"response":{"text":{"type":"text","value":"\mathbf{2x(x-3) = 0}\text{ has two solutions: }\mathbf{x = 0}\text{ and }\mathbf{x = 3}\text{. Each gives a separate intersection point.}"}}},{"id":"q_2_rule","chip":{"copy":"\mathbf{f_1(x) = f_2(x) \Rightarrow}\text{ intersection}"},"response":{"text":{"type":"text","value":"\text{When }\mathbf{f_1(x) = f_2(x)}\text{, both curves reach the same height at }\mathbf{x}\text{, that's the intersection point!}"}}}]}]}}

