        vLine = slopeTri.append("line");

    function updateSlopeTriangle(d) {
        const p1 = otherPoint(d),
            p2 = d,
            corner = { x: p2.x, y: p1.y };
        console.log("p1, p2, corner", p1, p2, corner);

        hLine
            .attr("x1", xScale(p1.x)).attr("y1", yScale(p1.y))
            .attr("x2", xScale(corner.x)).attr("y2", yScale(corner.y));
        vLine
            .attr("x1", xScale(corner.x)).attr("y1", yScale(corner.y))
            .attr("x2", xScale(p2.x)).attr("y2", yScale(p2.y));
    }

    // --- Recompute on drag from whichever point ---
    function recomputeLineFrom(d) {
        const other = otherPoint(d);
        return computeLineFromPoints(other, d);
    }

    // --- Drag Behavior ---
    const dragHandler = d3.drag()
        .on("start", function(event, d) {
            d3.select(this).raise().attr("stroke", "black").attr("stroke-width", 2);
            [ this, linePath.node(), hLine.node(), vLine.node() ]
                .forEach(el => d3.select(el).style("transition", "none"));
        })
        .on("drag", function(event, d) {
            const [mx, my] = d3.pointer(event, svg.node());
            console.log("mx, my", mx, my);
            d.x = Math.max(xRange[0], Math.min(xRange[1],
                xScale.invert(mx - margin.left)));
            d.y = Math.max(yRange[0], Math.min(yRange[1],
                yScale.invert(my - margin.top)));
            console.log("d.x, d.y", d.x, d.y);
            d3.select(this)
                .attr("cx", xScale(d.x))
                .attr("cy", yScale(d.y));

            ({ verticalX, eq: currentEquation } = recomputeLineFrom(d));
            console.log("verticalX, currentEquation", verticalX, currentEquation);
            const seg = getBoundedLineSegment(currentEquation, verticalX, xRange, yRange);
            console.log("seg", seg);
            if (seg.length === 2) linePath.datum(seg).attr("d", lineGenerator);
            else                   linePath.attr("d", null);

            updateSlopeTriangle(d);

            segment = seg;

        })
        .on("end", function(event, d) {
            [ this, linePath.node(), hLine.node(), vLine.node() ]
                .forEach(el => d3.select(el).style("transition", null));

            d.x = Math.round(d.x);
            d.y = Math.round(d.y);
            d.x = Math.max(xRange[0], Math.min(xRange[1], d.x));
            d.y = Math.max(yRange[0], Math.min(yRange[1], d.y));

            d3.select(this)
                .attr("cx", xScale(d.x))
                .attr("cy", yScale(d.y))
                .attr("stroke", "var(--whale-stroke)")
                .attr("stroke-width", 1);

            console.log("cx, cy", xScale(d.x), yScale(d.y));

            ({ verticalX, eq: currentEquation } = recomputeLineFrom(d));
            const seg = getBoundedLineSegment(currentEquation, verticalX, xRange, yRange);
            if (seg.length === 2) linePath.datum(seg).attr("d", lineGenerator);
            else                   linePath.attr("d", null);

            updateSlopeTriangle(d);

            segment = seg;

        });

    function getOutputVariables() {
        const slope = (segment[1].y - segment[0].y) / (segment[1].x - segment[0].x);
        const yIntercept = segment[0].y - slope * segment[0].x;
        return {
            "slope": slope,
            "y-intercept": yIntercept
        };
    }

    pointCircles
        .filter(d => d.draggable)
        .call(dragHandler);

    // --- Initial Slope Triangle ---
    pointsToPlot.forEach(p => { if (p.draggable) updateSlopeTriangle(p); });
